import java.sql.*; import java.util.*;
public class RegistrationDAO {
    public boolean isDuplicate(Registration r)throws SQLException{String s="SELECT COUNT(*) FROM registrations WHERE student_id=? AND event_name=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,r.getStudentId());p.setString(2,r.getEventName());try(ResultSet rs=p.executeQuery()){rs.next();return rs.getInt(1)>0;}}}
    public void insert(Registration r)throws SQLException{String s="INSERT INTO registrations(student_id,student_name,event_name,department) VALUES(?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,r.getStudentId());p.setString(2,r.getStudentName());p.setString(3,r.getEventName());p.setString(4,r.getDepartment());p.executeUpdate();}}
    public List<Registration> findByEvent(String event)throws SQLException{List<Registration> l=new ArrayList<>();String s="SELECT id,student_id,student_name,event_name,department FROM registrations WHERE event_name LIKE ? ORDER BY id";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,event);try(ResultSet rs=p.executeQuery()){while(rs.next()){Registration r=new Registration(rs.getString("student_id"),rs.getString("student_name"),rs.getString("event_name"),rs.getString("department"));r.setId(rs.getInt("id"));l.add(r);}}}return l;}
}
